    source_sha VARCHAR2(64) NOT NULL, state VARCHAR2(20) NOT NULL,
    original_active CHAR(1), original_nullable CHAR(1),
    before_json CLOB, after_json CLOB,
    saved_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)~';
  END IF;
  demand(count_sql('SELECT COUNT(*) FROM user_tab_columns WHERE table_name = ''AIPS_MIG_BACKUP''') = 9,
    'Unexpected AIPS_MIG_BACKUP definition. Do not reuse or delete an unknown backup.');
  IF count_sql('SELECT COUNT(*) FROM AIPS_MIG_BACKUP') > 0 THEN
    EXECUTE IMMEDIATE 'SELECT source_sha, state, original_active, original_nullable FROM AIPS_MIG_BACKUP WHERE object_name = ''HEADER'''
      INTO l_sql, l_state, l_original_active, l_original_nullable;
    demand(count_sql('SELECT COUNT(*) FROM AIPS_MIG_BACKUP WHERE migration_id <> ''ROLES_CATALOG_20260910_V1'' OR source_sha <> ''ac5e58d77f23e58fe9626add1dacc803c9d39b24a4c6b3e9fc8679944ee8aab1''') = 0,
      'Backup belongs to another migration or source revision. Stopped.');
    demand(count_sql('SELECT COUNT(*) FROM AIPS_MIG_BACKUP') = 9, 'Incomplete backup manifest. Stopped.');
  ELSE
    l_state := NULL;
  END IF;
  IF l_state = 'APPLIED' THEN
    lock_tables;
    check_snapshot('PROJECT_TYPES', 'AFTER_JSON');
    check_snapshot('INTERESTS', 'AFTER_JSON');
    check_snapshot('CUSTOMER_MAPPING', 'AFTER_JSON');
    check_snapshot('DELIVERABLES', 'AFTER_JSON');
    check_snapshot('DELIVERABLE_SKILLS', 'AFTER_JSON');
    check_snapshot('APP_ROLES', 'AFTER_JSON');
    check_snapshot('ROLE_PERMISSIONS', 'AFTER_JSON');
    check_snapshot('APP_USER_ROLES', 'AFTER_JSON');
    ROLLBACK;
    DBMS_OUTPUT.PUT_LINE('ALREADY APPLIED AND VERIFIED. No changes were made.');
    RETURN;
  END IF;
  demand(l_state IS NULL OR l_state = 'PREPARED', 'Migration was rolled back or has an unknown state. Use a new reviewed migration.');

